parameters.jsCode:
return [{
  json: {
    target_url: 'https://demo.realworld.show',
    target_api: 'https://api.realworld.show/api/articles',
    ping_start_ms: Date.now(),
    check_timestamp: new Date().toISOString()
  }
}];

const response = $input.first()?.json || {};
const initData = $('Code: Initialize Health Ping').first()?.json || {};
const endMs = Date.now();
const latency = endMs - (initData.ping_start_ms || endMs);

// n8n returns status code in execution metadata or response
const statusCode = response.statusCode || ($input.first()?.error ? ($input.first()?.error?.response?.status || 500) : 200);
const isSuccess = statusCode === 200 && !response.error;

return [{
  json: {
    url: initData.target_url,
    statusCode: statusCode,
    is_healthy: isSuccess,
    latency_ms: latency,
    timestamp: initData.check_timestamp,
    error_message: response.error?.message || (isSuccess ? null : 'Non-200 HTTP response received')
  }
}];

const retryResponse = $input.first()?.json || {};
const initialMetrics = $('Code: Calculate Latency & Status').first()?.json || {};

const retryStatusCode = retryResponse.statusCode || ($input.first()?.error ? 500 : 200);
const stillFailed = retryStatusCode !== 200;

return [{
  json: {
    target_url: initialMetrics.url,
    initial_status: initialMetrics.statusCode,
    retry_status: retryStatusCode,
    confirmed_down: stillFailed,
    initial_latency_ms: initialMetrics.latency_ms,
    timestamp: new Date().toISOString(),
    severity: 'CRITICAL_INCIDENT'
  }
}];

